package dev.networkwatch;import java.util.*;
public record Baseline(double meanBytes,double standardDeviation,Set<String> knownRegions){public static Baseline from(List<Analyzer.Event> events){var traffic=events.stream().filter(e->e.kind().equals("traffic")).mapToDouble(Analyzer.Event::bytes).toArray();double mean=Arrays.stream(traffic).average().orElse(0),variance=Arrays.stream(traffic).map(x->Math.pow(x-mean,2)).average().orElse(0);return new Baseline(mean,Math.sqrt(variance),events.stream().map(Analyzer.Event::region).collect(java.util.stream.Collectors.toUnmodifiableSet()));}public boolean unusualBytes(long bytes){return bytes>meanBytes+Math.max(1,3*standardDeviation);}public Set<String> newRegions(List<Analyzer.Event> events){var out=new TreeSet<String>();events.stream().map(Analyzer.Event::region).filter(x->!knownRegions.contains(x)).forEach(out::add);return out;}}
